//! Babel platform data Exaudio doesn't carry in its source, embedded from the pinned private Babel
//! data bundle that `build.rs` reads from the build cache (`babel-data.json`; fetch or republish
//! it with `tools/update-babel-data.ps1`).

macro_rules! bundled {
    ($file:literal) => {
        include_str!(concat!(env!("OUT_DIR"), "/babel-data/", $file))
    };
}

/// Babel's native linter configured for gold-non-bg transcription, per language, with its rule
/// tables (generated by `tools/lint-parity/generate.mjs`).
pub const LINT_DATA_JSON: &str = bundled!("babel-lint-data.json");

/// Babel's localized error-category bucket and category names, by language.
pub const ERROR_CATEGORY_NAMES_JSON: &str = bundled!("error-category-names.json");

/// Lint parity corpus with the issues Babel's linter and the Helper custom linter report for
/// each case (generated by `tools/lint-parity/generate.mjs`), for the linter ports' tests.
pub const LINT_PARITY_JSON: &str = bundled!("lint-parity.json");
